-- Internal display assignments and operational help are never static assets.
create table if not exists private.company_client_configuration (
 company_id uuid primary key references public.companies(id) on delete cascade,
 configuration jsonb not null default '{}'::jsonb check (jsonb_typeof(configuration) = 'object'),
 updated_at timestamptz not null default now()
);
alter table private.company_client_configuration enable row level security;
revoke all on private.company_client_configuration from public, anon, authenticated;
grant select on private.company_client_configuration to authenticated;
create policy company_client_configuration_read
 on private.company_client_configuration for select to authenticated
 using ((select private.sf_company_profile_can_read(company_id)));

create or replace function public.company_private_client_configuration(p_company_id uuid)
returns jsonb language plpgsql stable security invoker set search_path = '' as $function$
begin
 if auth.uid() is null or not private.sf_company_profile_can_read(p_company_id) then
  raise exception using errcode = '42501', message = 'Unternehmenszugriff verweigert';
 end if;
 if private.sf_is_manager(p_company_id, true) then
  perform private.sf_assert_aal2('company_private_client_configuration');
 end if;
 return coalesce((select c.configuration from private.company_client_configuration c
                  where c.company_id = p_company_id), '{}'::jsonb);
end;
$function$;
revoke all on function public.company_private_client_configuration(uuid) from public, anon;
grant execute on function public.company_private_client_configuration(uuid) to authenticated;

insert into private.company_client_configuration(company_id, configuration)
 select id, '{"employeeDisplay": {"order": ["2001", "26", "2048", "2059", "37", "119", "2015"], "priorityPersonnelNos": ["2001", "26", "2048"], "byTeam": false, "colored": true, "colorGroups": {"yellow": ["2001", "26", "2048"], "turquoise": ["2059", "37", "119", "2015"]}}, "helpArticles": {"auto": {"Welche Regeln nutzt die Auto-Planung?": "Die Auto-Planung prüft Aktivstatus, Schichtfreigaben, Qualifikationen, Abwesenheiten, Doppelbelegungen, SOLL-Stärken und verbindliche Mitarbeiter- und Teamregeln. Es gelten die für das ausgewählte Unternehmen geschützten Planungsregeln. Konflikte bleiben sichtbar und werden nicht durch eine automatische Besetzung übergangen.", "Welche Stunden- und Schichtgrenzen gelten?": "Für die bestätigten Modelle gilt höchstens 190 Stunden je Kalendermonat und höchstens 40 Stunden je Kalenderwoche (Montag bis Sonntag). Niedrigere persönliche Vertragsgrenzen bleiben verbindlich. Im 10-Stunden-Modell werden höchstens 18 Dienste automatisch geplant. Im 8-Stunden-Modell sind bei Vollzeit bis zu 23 Dienste beziehungsweise 184 automatisch geplante Stunden möglich; für Teilzeit gelten die niedrigeren Vertragsstunden. 180 Stunden bleiben das Vollzeit-Ziel. Nachtdienste werden für Wochen- und Monatsgrenzen mit ihren tatsächlichen Zeitanteilen gezählt.", "Wie viele Dienste und Nächte sind am Stück erlaubt?": "Höchstens vier Dienste und höchstens drei Nachtdienste am Stück. Zwischen Arbeitsblöcken liegen mindestens zwei vollständig freie Kalendertage und mindestens 48 tatsächliche Stunden Ruhe. Nach einem Nachtblock liegen mindestens drei vollständig freie Kalendertage. Die frühere Ausnahme für kurze OT-Blöcke erlaubt keine verkürzte Erholung mehr.", "Wie werden freie Tage nach einer Nachtschicht gezählt?": "Ein freier Kalendertag enthält keine Arbeitszeit. Endet die letzte Nachtschicht am 4. Januar morgens, zählt der 4. Januar noch als Arbeitstag. Nach drei vollständig freien Tagen am 5., 6. und 7. Januar ist der nächste Dienst frühestens am 8. Januar möglich. Die Prüfung gilt auch über Monatsgrenzen und Zeitumstellungen.", "Was passiert bei nicht erreichbarem Monats-SOLL?": "Das Monats-SOLL und eine vollständige Besetzung heben feste Grenzen nicht auf. Der Planer zeigt Zielabweichungen und offene Positionen. Feste Mitarbeiter- und Teamregeln werden berücksichtigt; widersprechen sie den Belastungsgrenzen, bleibt der Konflikt offen. Innerhalb eines Blocks wird möglichst dieselbe Schicht bevorzugt; Wechsel folgen möglichst Früh → Spät → Nacht. O3 → O1/O2/TL am Folgetag bleibt gesperrt.", "Wie plane ich mehrere Monate?": "Bei aktivierten Erholungsregeln kannst du einen bis zwölf zusammenhängende Monate als Vorschau planen. Die Mindestbesetzung für OT2 und die gemeinsame Teamleitung wird zuerst über den gesamten Zeitraum verteilt; anschließend werden die übrigen Dienste ergänzt. Im ausgewählten Unternehmen gelten montags bis freitags mindestens zwei OT2 und täglich eine gemeinsame Teamleitung für Leipzig/Recklinghausen. Ein zusätzlich hinterlegter dritter OT2 bleibt als offener Bedarf sichtbar, blockiert aber bei erfüllter Mindestbesetzung die Übernahme nicht. Prüfe Pflichtlücken, Stundenabweichungen und geschützte Dienste. Erst die bestätigte Übernahme speichert einen Entwurf. Die Veröffentlichung bleibt ein eigener Schritt. Veränderte Daten erfordern eine neue Vorschau.", "Wie werden Mitarbeiter mit festen Schichtfreigaben geplant?": "Reguläre OT1-, OT2- und OT3-Dienste sind ausschließlich für Personalnummern 2001, 26 und 2048 vorgesehen. Die konkrete OT-Art richtet sich nach Bedarf und O1-/O3-Abdeckung. Flexible Arbeitsblöcke unter den bestätigten Erholungs- und Stundengrenzen ersetzen die früheren festen OT2-Tagesfolgen. Fehlende Besetzungen und unerreichte Stunden bleiben sichtbar.", "Welche Feiertage gelten für OT-Dienste?": "Das gesonderte Schichtmodell OT gilt an Samstagen, Sonntagen und gesetzlichen Feiertagen am hinterlegten Einsatzort. Leipzig verwendet Sachsen, Recklinghausen Nordrhein-Westfalen. Maßgeblich ist der Standort im Mitarbeiterprofil, nicht der Wohnort. Für OT bleiben die jeweiligen persönlichen Schichtfreigaben erforderlich. Fehlt ein bekannter Einsatzort, wird kein örtlicher Feiertag unterstellt."}}}'::jsonb from public.companies where id = '3dbc2d99-78d7-4b82-bcaf-fe11db8213d3'::uuid
 on conflict (company_id) do update set configuration=excluded.configuration, updated_at=now();

insert into private.company_client_configuration(company_id, configuration)
 select id, '{"employeeDisplay": {"order": ["2001", "26", "2048", "2059", "37", "119", "2015"], "priorityPersonnelNos": ["2001", "26", "2048"], "byTeam": true, "colored": false, "colorGroups": {"yellow": ["2001", "26", "2048"], "turquoise": ["2059", "37", "119", "2015"]}}, "helpArticles": {"auto": {"Welche Regeln nutzt die Auto-Planung?": "Die Auto-Planung prüft Aktivstatus, Schichtfreigaben, Qualifikationen, Abwesenheiten, Doppelbelegungen, SOLL-Stärken und verbindliche Mitarbeiter- und Teamregeln. Es gelten die für das ausgewählte Unternehmen geschützten Planungsregeln. Konflikte bleiben sichtbar und werden nicht durch eine automatische Besetzung übergangen.", "Welche Stunden- und Schichtgrenzen gelten?": "Für die bestätigten Modelle gilt höchstens 190 Stunden je Kalendermonat und höchstens 40 Stunden je Kalenderwoche (Montag bis Sonntag). Niedrigere persönliche Vertragsgrenzen bleiben verbindlich. Im 10-Stunden-Modell werden höchstens 18 Dienste automatisch geplant. Im 8-Stunden-Modell sind bei Vollzeit bis zu 23 Dienste beziehungsweise 184 automatisch geplante Stunden möglich; für Teilzeit gelten die niedrigeren Vertragsstunden. 180 Stunden bleiben das Vollzeit-Ziel. Nachtdienste werden für Wochen- und Monatsgrenzen mit ihren tatsächlichen Zeitanteilen gezählt.", "Wie viele Dienste und Nächte sind am Stück erlaubt?": "Höchstens vier Dienste und höchstens drei Nachtdienste am Stück. Zwischen Arbeitsblöcken liegen mindestens zwei vollständig freie Kalendertage und mindestens 48 tatsächliche Stunden Ruhe. Nach einem Nachtblock liegen mindestens drei vollständig freie Kalendertage. Die frühere Ausnahme für kurze OT-Blöcke erlaubt keine verkürzte Erholung mehr.", "Wie werden freie Tage nach einer Nachtschicht gezählt?": "Ein freier Kalendertag enthält keine Arbeitszeit. Endet die letzte Nachtschicht am 4. Januar morgens, zählt der 4. Januar noch als Arbeitstag. Nach drei vollständig freien Tagen am 5., 6. und 7. Januar ist der nächste Dienst frühestens am 8. Januar möglich. Die Prüfung gilt auch über Monatsgrenzen und Zeitumstellungen.", "Was passiert bei nicht erreichbarem Monats-SOLL?": "Das Monats-SOLL und eine vollständige Besetzung heben feste Grenzen nicht auf. Der Planer zeigt Zielabweichungen und offene Positionen. Feste Mitarbeiter- und Teamregeln werden berücksichtigt; widersprechen sie den Belastungsgrenzen, bleibt der Konflikt offen. Innerhalb eines Blocks wird möglichst dieselbe Schicht bevorzugt; Wechsel folgen möglichst Früh → Spät → Nacht. O3 → O1/O2/TL am Folgetag bleibt gesperrt.", "Wie plane ich mehrere Monate?": "Bei aktivierten Erholungsregeln kannst du einen bis zwölf zusammenhängende Monate als Vorschau planen. Verbindliche Mindestbesetzungen werden zuerst über den gesamten Zeitraum verteilt; anschließend werden die übrigen Dienste ergänzt. Prüfe Pflichtlücken, Stundenabweichungen und geschützte Dienste. Erst die bestätigte Übernahme speichert einen Entwurf. Veränderte Daten erfordern eine neue Vorschau.", "Wie werden Mitarbeiter mit festen Schichtfreigaben geplant?": "Für reguläre FD-Dienste sind ausschließlich die hinterlegten Personalnummern 2001, 26 und 2048 freigegeben. FD-WE wird anhand der Freigaben unter den Team-Mitarbeitern verteilt. Die Planung berücksichtigt die bestätigten Erholungs- und Stundengrenzen; fehlende Besetzungen und unerreichte Stunden bleiben sichtbar.", "Welche Feiertage gelten für OT-Dienste?": "Das gesonderte Schichtmodell OT gilt an Samstagen, Sonntagen und gesetzlichen Feiertagen am hinterlegten Einsatzort. Leipzig verwendet Sachsen, Recklinghausen Nordrhein-Westfalen. Maßgeblich ist der Standort im Mitarbeiterprofil, nicht der Wohnort. Für OT bleiben die jeweiligen persönlichen Schichtfreigaben erforderlich. Fehlt ein bekannter Einsatzort, wird kein örtlicher Feiertag unterstellt."}}}'::jsonb from public.companies where id = '1f23f5a3-1cbb-430f-af90-36ed34004440'::uuid
 on conflict (company_id) do update set configuration=excluded.configuration, updated_at=now();
